const crypto = require('crypto');

const secret = process.env.N8N_WEBHOOK_HMAC_SECRET;
if (!secret) {
  throw new Error('N8N_WEBHOOK_HMAC_SECRET environment variable is not configured');
}

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'] || headers['X-LendLoop-Timestamp'];
const signature = headers['x-lendloop-signature'] || headers['X-LendLoop-Signature'];

if (!timestamp || !signature || !/^\d+$/.test(String(timestamp))) {
  throw new Error('Missing or malformed HMAC headers');
}

const skewMs = Math.abs(Date.now() - Number(timestamp));
if (skewMs > 300000) {
  throw new Error('Webhook timestamp outside 5-minute replay window');
}

const rawBody = item.binary?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

const expectedHex = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

const actualBuf = Buffer.from(String(signature).trim().toLowerCase(), 'hex');
const expectedBuf = Buffer.from(expectedHex, 'hex');
if (actualBuf.length !== expectedBuf.length || !crypto.timingSafeEqual(actualBuf, expectedBuf)) {
  throw new Error('Invalid HMAC signature');
}

const payload = typeof item.json.body === 'string' ? JSON.parse(item.json.body) : item.json.body;

// Data minimization: forward only the notification fields required
let subject = `[LendLoop] Tool update: ${payload.toolName}`;
let message = `Status for ${payload.toolName} is now ${payload.status}.`;
if (payload.eventType === 'request_created_webhook') {
  subject = `[LendLoop] New borrow request for ${payload.toolName}`;
  message = `Hi ${payload.recipientName}, ${payload.counterpartyName} requested to borrow "${payload.toolName}" from ${payload.startDate} to ${payload.endDate}.`;
} else {
  subject = `[LendLoop] Loan status updated: ${payload.status}`;
  message = `Hi ${payload.recipientName}, your loan for "${payload.toolName}" (${payload.startDate} to ${payload.endDate}) with ${payload.counterpartyName} is now ${payload.status}.`;
}

return [{
  json: {
    verified: true,
    loanId: payload.loanId,
    recipientEmail: payload.recipientEmail,
    recipientName: payload.recipientName,
    subject,
    message
  }
}];

const data = $input.first().json;
// Mock notification dispatch log (swap with SMTP / Slack / Discord node using n8n credentials in production)
console.log(JSON.stringify({
  channel: 'notification_mock',
  to: data.recipientEmail,
  subject: data.subject,
  message: data.message,
  loanId: data.loanId,
  dispatchedAt: new Date().toISOString()
}));
return [{ json: { ok: true, loanId: data.loanId, recipientEmail: data.recipientEmail } }];
